<script setup>
import { computed, ref } from 'vue'
import { ChevronLeft, ChevronRight } from 'lucide-vue-next'
import { featuredProducts as slides } from '../data/site'
import { useLocale } from '../composables/useLocale'
import GradientButton from './GradientButton.vue'
const { t, tx } = useLocale(), active = ref(0)
const current = computed(() => slides[active.value])
function move(direction) { active.value = (active.value + direction + slides.length) % slides.length }
</script>
<template><section class="carousel-section" :aria-label="t('common.collection')"><div class="container carousel-layout">
<article class="feature-product"><img src="/images/ceramics/gathering.jpg" :alt="t('common.imageNote')" loading="lazy" width="640" height="640" /><div class="feature-product-copy"><span class="eyebrow">DLIM HOME</span><h2>{{ t('about.shopTitle') }}</h2><GradientButton to="/products">{{ t('common.explore') }}</GradientButton></div></article>
<div class="carousel" role="region" aria-roledescription="carousel" :aria-label="t('common.collection')" @keydown.left.prevent="move(-1)" @keydown.right.prevent="move(1)"><div class="carousel-viewport"><div class="carousel-track" :style="{ transform: `translateX(-${active * 100}%)` }"><article v-for="(product, index) in slides" :key="product.handle" class="feature-product carousel-slide" :aria-hidden="index !== active" :inert="index !== active" role="group" :aria-label="`${index + 1} ${t('common.of')} ${slides.length}: ${tx(product.name)}`"><img class="carousel-object" :src="product.image" :alt="tx(product.name)" loading="lazy" width="640" height="640" /><div class="feature-product-copy"><span class="eyebrow">{{ tx(product.subtitle) }}</span><h2>{{ tx(product.name) }}</h2><GradientButton :to="`/product/${product.handle}`">{{ t('common.view') }}</GradientButton></div></article></div><div class="carousel-arrows"><button type="button" class="icon-button" :aria-label="t('common.previous')" @click="move(-1)"><ChevronLeft /></button><button type="button" class="icon-button" :aria-label="t('common.next')" @click="move(1)"><ChevronRight /></button></div></div><div class="carousel-dots" :aria-label="t('common.choose')"><button v-for="(product, index) in slides" :key="product.handle" type="button" :class="{ active: index === active }" :aria-label="`${t('common.show')} ${tx(product.name)}`" :aria-current="index === active ? 'true' : undefined" @click="active = index"><span /></button></div><p class="sr-only" aria-live="polite">{{ tx(current.name) }}, {{ active + 1 }} {{ t('common.of') }} {{ slides.length }}</p></div>
</div></section></template>